  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s)))
    case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s)))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
