  function expr() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const tk = toks[p++]
    if (tk.t === 'num') return { t: 'num', v: tk.v }
    if (tk.t === 'op') {
      if (tk.v === '(') {
        const e = expr()
        if (!isOp(')')) fail()
        p++
        return { t: 'paren', e }
      }
      fail()
    }
    const name = tk.v
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          const a = expr()
          if (a.t === 'range') okRanges++
          args.push(a)
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { t: 'call', name: name.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') fail()
      const w2 = toks[p++].v
      if (isOp('(')) fail()
      ranges++
      return { t: 'range', a: parseAddr(name), b: parseAddr(w2) }
    }
    const up = name.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddr(name) }
  }
  try {
    const e = expr()
    if (p !== toks.length) fail()
    return { ast: e, misplaced: ranges !== okRanges }
  } catch (x) {
    if (x.message === 'g') return null
    throw x
  }
}

function collectDeps(n, out) {
  switch (n.t) {
    case 'ref': if (n.a) out.set(key(n.a), n.a); break
    case 'range':
      if (n.a && n.b) {
        for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
          for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) out.set(colName(c) + r, { col: c, row: r })
      }
      break
    case 'bin': collectDeps(n.l, out); collectDeps(n.r, out); break
    case 'un': case 'paren': collectDeps(n.e, out); break
    case 'call': n.args.forEach((a) => collectDeps(a, out)); break
  }
}

const parsed = new Map()
for (const [k, c] of cells) {
  if (c.content[0] === '=') parsed.set(k, parseFormula(c.content.slice(1)))
}

const sortedCells = [...cells.values()].sort((x, y) => x.addr.col - y.addr.col || x.addr.row - y.addr.row)

if (mode === 'deps') {
  let out = ''
  for (const c of sortedCells) {
    const k = key(c.addr)
    const deps = new Map()
    const pr = parsed.get(k)
    if (pr) collectDeps(pr.ast, deps)
    const list = [...deps.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += k + ':' + list.map((a) => ' ' + key(a)).join('') + '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const busy = new Set()
function cellValue(a) {
  if (!a) return err('#REF!')
  const k = key(a)
  if (memo.has(k)) return memo.get(k)
  const c = cells.get(k)
  if (!c) return num(0)
  if (busy.has(k)) return err('#CYCLE!')
  busy.add(k)
  let v
  const content = c.content
  if (content[0] === '=') {
    const pr = parsed.get(k)
    v = !pr || pr.misplaced ? err('#ERR!') : evalNode(pr.ast)
  } else if (content === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) v = num(Number(content))
  else if (ERRS.includes(content)) v = err(content)
  else v = { k: 's', v: content }
  busy.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.k === 'e' || v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }
function compare(l, r) {
  if (l.k !== r.k) return rank[l.k] - rank[r.k]
  if (l.k === 's') return cmpStr(l.v, r.v)
  const a = Number(l.v), b = Number(r.v)
  return a < b ? -1 : a > b ? 1 : 0
}

function rangeValues(n) {
  if (!n.a || !n.b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
    for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) out.push(cellValue({ col: c, row: r }))
  return out
}
function argValues(args) {
  const out = []
  for (const a of args) {
    if (a.t === 'range') for (const v of rangeValues(a)) out.push(v)
    else out.push(evalNode(a))
  }
  return out
}
function single(a) {
  if (a.t === 'range') {
    const vs = rangeValues(a)
    return vs.length === 1 ? vs[0] : err('#ERR!')
  }
  return evalNode(a)
}

function evalNode(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'paren': return evalNode(n.e)
    case 'ref': return cellValue(n.a)
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.k === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (l.k === 'e') return l
      const r = evalNode(n.r)
      if (r.k === 'e') return r
      if (CMP.includes(n.op)) {
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = single(args[0])
    if (c.k === 'e') return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return single(args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const v = toNum(single(args[0]))
    if (v.k === 'e') return v
    return num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = argValues(args)
  for (const v of vals) if (v.k === 'e') return v
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s)))
    case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s)))
    default: return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

function show(v) {
  if (v.k === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

let out = ''
for (const c of sortedCells) out += key(c.addr) + '=' + show(cellValue(c.addr)) + '\n'
process.stdout.write(out)
